SourceCode.Declaration:
/// <summary>
/// This class is used to post a list of inventory journals
/// </summary>
class METAutoPostInvJournalService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// This method posts a list of inventory journals
    /// </summary>
    /// <param name = "_contract">data contract for the <c>METAutoPostInvJournalService</c> service</param>
    /// <returns>reponse as a data contract <c>METJournalCollectionResponseContract</c> </returns>
    public METJournalCollectionResponseContract process(METAutoPostInvJournalContract _contract)
    {
        InventJournalTable          inventJournalTable;
        boolean                     journalTransferErrors;
        JournalCheckPost            journalCheckPost;
        InventJournalId             journalId;

        ListEnumerator                       journalListEnumerator  = _contract.getJournalList().getEnumerator();
        List                                 journalResponseList = new List(Types::Class);
        METJournalCollectionResponseContract response = new METJournalCollectionResponseContract();
        METAutoPostInvJournalRequestContract requestContract;

        #OCCRetryCount

        changecompany(_contract.parmDataArea())
        {
            journalTransferErrors = _contract.parmTransferError();

            while(journalListEnumerator.moveNext())
            {
                METAutoPostInvJournalResponseContract journalReponse = new METAutoPostInvJournalResponseContract();

                try
                {
                    requestContract = journalListEnumerator.current();

                    journalId = requestContract.parmInventJournalId();

                    journalReponse.parmJournalId(journalId);

                    select firstonly inventJournalTable
                        where inventJournalTable.JournalId == journalId
                        && inventJournalTable.Posted == NoYes::No;

                    journalCheckPost = InventJournalCheckPost::newPostJournal(inventJournalTable);
            
                    if (journalCheckPost.validate())
                    {
                        journalCheckPost.parmShowInfoResult(false);
                        journalCheckPost.parmTransferErrors(journalTransferErrors);
                        journalCheckPost.runOperation();

                        journalReponse.parmSuccess(NoYes::Yes);
                        journalReponse.parmMessage("@MET:PostingSuccess");
                    }
                    else
                    {
                        journalReponse.parmSuccess(NoYes::No);
                        journalReponse.parmMessage("@MET:PostingValidationFailed");
                        throw error("@MET:InventoryPostingError");
                    }
                }
                catch(Exception::Deadlock)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        journalReponse.parmSuccess(NoYes::No);
                        journalReponse.parmMessage("@MET:InventoryPostingDeadlockError");
                        throw Exception::Error;
                    }
                    else
                    {
                        retry;
                    }
                }
                catch(Exception::UpdateConflict)
                {
                    if (appl.ttsLevel() == 0)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            throw Exception::UpdateConflictNotRecovered;
                        }
                        else
                        {
                            retry;
                        }
                    }
                    else
                    {
                        journalReponse.parmSuccess(NoYes::No);
                        journalReponse.parmMessage("@MET:InventoryPostingUpdateConflictError");
                        throw Exception::UpdateConflict;
                    }
                }
                catch(Exception::CLRError)
                {
                    System.Exception interopException = CLRInterop::getLastException();
                    journalReponse.parmSuccess(NoYes::No);
                    journalReponse.parmMessage(interopException.ToString());
                }
                catch(Exception::Error)
                {
                    journalReponse.parmSuccess(NoYes::No);
                    journalReponse.parmMessage("@MET:InventoryPostingError");
                }

                journalResponseList.addEnd(journalReponse);
            }
        }

        response.parmJournalPostingResponseList(journalResponseList);
        return response;
    }
